import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"GUI Templates","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/station/gui.md","filePath":"en/modules/station/gui.md","lastUpdated":0}`),a={name:`en/modules/station/gui.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="gui-templates" tabindex="-1">GUI Templates <a class="header-anchor" href="#gui-templates" aria-label="Permalink to “GUI Templates”">​</a></h1><p>EmakiStation has four window templates under <code>plugins/EmakiStation/gui/</code>.</p><table tabindex="0"><thead><tr><th>Template</th><th>Window</th><th>Station configuration key</th></tr></thead><tbody><tr><td><code>station_catalog.yml</code></td><td>Recipe catalog (page 1)</td><td><code>layout</code></td></tr><tr><td><code>station_preview.yml</code></td><td>Material preview (page 2)</td><td><code>preview_layout</code></td></tr><tr><td><code>station_queue.yml</code></td><td>Craft queue (page 3)</td><td><code>queue_layout</code></td></tr><tr><td><code>station_dismantle.yml</code></td><td>Dismantle window</td><td><code>layout</code> of a dismantle station</td></tr></tbody></table><p>The first three form the three-page crafting flow: the catalog submits on left click and opens the material preview on right click; the preview confirms the submission; the queue page views, cancels, claims and buys queue slots. The dismantle window is separate and entered through <code>/emakistation dismantle &lt;station&gt;</code>.</p><h2 id="slots-must-declare-type-explicitly" tabindex="-1">Slots Must Declare <code>type</code> Explicitly <a class="header-anchor" href="#slots-must-declare-type-explicitly" aria-label="Permalink to “Slots Must Declare type Explicitly”">​</a></h2><p>EmakiStation slots <strong>must declare <code>type</code> explicitly</strong>. The CoreLib template parser only infers types for a few Forge-specific key names; a custom key name without <code>type</code> is nothing but decoration.</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">slots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  recipe_list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    slots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">11</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;recipe_list&quot;</span></span></code></pre></div><h2 id="recipe-catalog-types" tabindex="-1">Recipe Catalog Types <a class="header-anchor" href="#recipe-catalog-types" aria-label="Permalink to “Recipe Catalog Types”">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>Purpose</th></tr></thead><tbody><tr><td><code>recipe_list</code></td><td>List recipes. <strong>Required</strong>, or layout validation fails.</td></tr><tr><td><code>queue_open</code></td><td>Open the craft queue page.</td></tr><tr><td><code>batch_multiplier</code></td><td>Cycle the multiplier; left click increases, right click decreases.</td></tr><tr><td><code>output_toggle</code></td><td>Switch output routing.</td></tr><tr><td><code>prev_page</code> / <code>next_page</code> / <code>page_info</code></td><td>Pagination.</td></tr><tr><td><code>close</code></td><td>Close the window.</td></tr></tbody></table><p>This page has <strong>no</strong> input slot. Players do not place materials into the window; materials are deducted from the merged inventory-plus-warehouse pool at submission time.</p><h2 id="material-preview-types" tabindex="-1">Material Preview Types <a class="header-anchor" href="#material-preview-types" aria-label="Permalink to “Material Preview Types”">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>Purpose</th></tr></thead><tbody><tr><td><code>material_list</code></td><td>List the selected recipe&#39;s material requirements. <strong>Required</strong>.</td></tr><tr><td><code>recipe_display</code></td><td>Show the recipe being previewed.</td></tr><tr><td><code>cost_display</code></td><td>Show the currency cost and the player&#39;s balance.</td></tr><tr><td><code>max_craftable</code></td><td>Show how many crafts the materials and balance allow, and jump straight to the maximum on click.</td></tr><tr><td><code>batch_multiplier</code></td><td>Cycle the multiplier.</td></tr><tr><td><code>confirm</code></td><td>Submit.</td></tr><tr><td><code>back</code></td><td>Return to the catalog, landing on the original page.</td></tr><tr><td><code>prev_page</code> / <code>next_page</code> / <code>page_info</code></td><td>Material list pagination.</td></tr><tr><td><code>close</code></td><td>Close the window.</td></tr></tbody></table><p>This page is read-only and does not accept inserted items.</p><h3 id="material-amount-display-rules" tabindex="-1">Material Amount Display Rules <a class="header-anchor" href="#material-amount-display-rules" aria-label="Permalink to “Material Amount Display Rules”">​</a></h3><table tabindex="0"><thead><tr><th>Requirement</th><th>Display</th></tr></thead><tbody><tr><td>≤ 99</td><td>The icon carries the real number, drawn directly by the client.</td></tr><tr><td>≥ 100</td><td>The icon amount is fixed at 1 with no number drawn; the real amount appears only in the lore&#39;s <code>%required_exact%</code>.</td></tr></tbody></table><p>Always keep <code>%required_exact%</code> in the lore, or players will have no way to learn large requirements.</p><p>Amounts of 65–99 exceed the natural stack size of most items, so the plugin temporarily raises the <code>max_stack_size</code> component of the rendered icon. That change applies only to the display icon inside the window and is never handed to the player.</p><h2 id="craft-queue-types" tabindex="-1">Craft Queue Types <a class="header-anchor" href="#craft-queue-types" aria-label="Permalink to “Craft Queue Types”">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>Purpose</th></tr></thead><tbody><tr><td><code>queue_view</code></td><td>List queue entries. <strong>Required</strong>.</td></tr><tr><td><code>capacity_display</code></td><td>Show used / ceiling along with where the ceiling comes from.</td></tr><tr><td><code>queue_purchase</code></td><td>Buy extra queue slots; left click buys one, Shift buys a whole batch.</td></tr><tr><td><code>claim_all</code></td><td>Claim every pending output.</td></tr><tr><td><code>back</code></td><td>Return to the catalog, landing on the original page.</td></tr><tr><td><code>prev_page</code> / <code>next_page</code> / <code>page_info</code></td><td>Queue pagination.</td></tr><tr><td><code>close</code></td><td>Close the window.</td></tr></tbody></table><p>This page is read-only and does not accept inserted items.</p><h2 id="dismantle-window-types" tabindex="-1">Dismantle Window Types <a class="header-anchor" href="#dismantle-window-types" aria-label="Permalink to “Dismantle Window Types”">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>Purpose</th></tr></thead><tbody><tr><td><code>dismantle_input</code></td><td>Show the item the recipe needs, i.e. the input icon of the selected recipe.</td></tr><tr><td><code>dismantle_item_display</code></td><td>Alias of <code>dismantle_input</code>.</td></tr><tr><td><code>dismantle_rolls_display</code></td><td>Show the roll count range (<code>%rolls_min%</code> / <code>%rolls_max%</code>).</td></tr><tr><td><code>dismantle_output_list</code></td><td>Output list across several paginated cells, using the <code>pool_entry</code> / <code>rolled_output</code> virtual items.</td></tr><tr><td><code>dismantle_confirm</code></td><td>Confirm the dismantle, or claim already-rolled outputs.</td></tr><tr><td><code>prev_page</code> / <code>next_page</code> / <code>page_info</code></td><td>Output list pagination.</td></tr><tr><td><code>back</code></td><td>Return to the catalog.</td></tr><tr><td><code>close</code></td><td>Close the window.</td></tr></tbody></table><h2 id="title-placeholders" tabindex="-1">Title Placeholders <a class="header-anchor" href="#title-placeholders" aria-label="Permalink to “Title Placeholders”">​</a></h2><table tabindex="0"><thead><tr><th>Placeholder</th><th>Available on</th></tr></thead><tbody><tr><td><code>%station_name%</code></td><td>Recipe catalog, craft queue, dismantle window.</td></tr><tr><td><code>%recipe_name%</code></td><td>Material preview.</td></tr><tr><td><code>%used%</code> / <code>%max%</code></td><td>Craft queue.</td></tr></tbody></table><p>These are internal template placeholders rendered by EmakiStation itself and unrelated to PlaceholderAPI.</p><h2 id="virtual-items-and-texts" tabindex="-1"><code>virtual_items</code> and <code>texts</code> <a class="header-anchor" href="#virtual-items-and-texts" aria-label="Permalink to “virtual_items and texts”">​</a></h2><p>All four templates have a <code>virtual_items</code> section defining the icon forms of list entries, for example <code>recipe_entry</code> / <code>recipe_locked</code> on the catalog, <code>material_satisfied</code> / <code>material_missing</code> / <code>confirm_blocked</code> on the preview, <code>queue_entry</code> / <code>queue_pending</code> / <code>purchase_unavailable</code> on the queue page, and <code>no_recipe</code> / <code>pool_entry</code> / <code>rolled_output</code> on the dismantle window.</p><p>The three crafting templates also have a <code>texts</code> section for configurable line fragments. The dismantle window has no <code>texts</code> section.</p>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};